  <title>DeployCloud Blog — Discover the latest in web development</title>
  <meta name="description" content="Engineering insights, product updates, and community stories from DeployCloud — the cloud deployment platform for developers." />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;450;500;600;700;800&display=swap" rel="stylesheet" />
  <link href="https://cdn.jsdelivr.net/npm/remixicon@4.5.0/fonts/remixicon.css" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #FAFAFA;
      --surface: #FFFFFF;
      --border: #E5E5E5;
      --border-hover: #D4D4D4;
      --text-primary: #171717;
      --text-secondary: #525252;
      --text-muted: #737373;
      --accent: #0072F5;
      --accent-hover: #005DD4;
      --accent-light: #EFF6FF;
      --tag-bg: #F4F4F5;
      --tag-text: #3F3F46;
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 14px;
      --radius-full: 9999px;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08), 0 2px 4px rgba(0,0,0,0.04);
      --shadow-hover: 0 8px 24px rgba(0,0,0,0.10), 0 2px 6px rgba(0,0,0,0.06);
      --transition: 0.18s ease;
    }

    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      background: var(--bg);
      color: var(--text-primary);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }
    button { cursor: pointer; font-family: inherit; }

    /* ─── LAYOUT ─── */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .section { padding: 64px 0; }

    /* ─── HEADER ─── */
    .header {
      position: sticky; top: 0; z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
    }
    .header-inner {
      display: flex; align-items: center; gap: 0;
      height: 60px;
    }
    .logo {
      display: flex; align-items: center; gap: 9px;
      font-size: 15px; font-weight: 700; color: var(--text-primary);
      letter-spacing: -0.3px; flex-shrink: 0; margin-right: 28px;
    }
    .logo-icon {
      width: 28px; height: 28px; border-radius: 7px;
      background: var(--text-primary);
      display: flex; align-items: center; justify-content: center;
    }
    .logo-icon i { color: white; font-size: 15px; }

    .main-nav { display: flex; align-items: center; gap: 2px; flex: 1; }
    .nav-item { position: relative; }
    .nav-btn {
      background: none; border: none; padding: 8px 12px;
      font-size: 14px; font-weight: 500; color: var(--text-secondary);
      border-radius: var(--radius-sm);
      display: flex; align-items: center; gap: 4px;
      transition: color var(--transition), background var(--transition);
    }
    .nav-btn:hover, .nav-item:hover .nav-btn { color: var(--text-primary); background: var(--tag-bg); }
    .nav-btn i { font-size: 13px; transition: transform 0.2s; }
    .nav-item:hover .nav-btn i { transform: rotate(180deg); }

    /* Dropdowns */
    .dropdown {
      position: absolute; top: calc(100% + 8px); left: 0;
      background: var(--surface); border: 1px solid var(--border);
      border-radius: var(--radius-lg); box-shadow: var(--shadow-md);
      opacity: 0; visibility: hidden; transform: translateY(-8px);
      transition: opacity 0.2s, transform 0.2s, visibility 0.2s;
      pointer-events: none; z-index: 200;
    }
    .nav-item:hover .dropdown { opacity: 1; visibility: visible; transform: translateY(0); pointer-events: all; }

    /* Mega menu */
    .mega-menu { width: 680px; padding: 24px; display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 24px; }
    .dropdown-col { display: flex; flex-direction: column; gap: 4px; }
    .dropdown-col-title { font-size: 11px; font-weight: 600; color: var(--text-muted); letter-spacing: 0.06em; text-transform: uppercase; padding: 0 8px; margin-bottom: 6px; }
    .dropdown-link {
      display: block; padding: 7px 8px; border-radius: var(--radius-sm);
      font-size: 13.5px; color: var(--text-secondary);
      transition: color var(--transition), background var(--transition);
    }
    .dropdown-link strong { display: block; font-weight: 600; color: var(--text-primary); font-size: 13px; }
    .dropdown-link span { font-size: 12px; color: var(--text-muted); line-height: 1.4; }
    .dropdown-link:hover { background: var(--accent-light); color: var(--accent); }
    .dropdown-link:hover strong { color: var(--accent); }

    /* Resources dropdown */
    .resources-menu { width: 380px; padding: 20px 24px; display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }

    /* Header actions */
    .header-actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }
    .btn-ghost {
      background: none; border: none; padding: 8px 12px;
      font-size: 14px; font-weight: 500; color: var(--text-secondary);
      border-radius: var(--radius-sm); transition: color var(--transition), background var(--transition);
      display: flex; align-items: center; gap: 6px;
    }
    .btn-ghost:hover { color: var(--text-primary); background: var(--tag-bg); }
    .btn-primary {
      background: var(--text-primary); color: white; border: none;
      padding: 8px 16px; font-size: 13.5px; font-weight: 600;
      border-radius: var(--radius-full); transition: background var(--transition), transform 0.1s;
    }
    .btn-primary:hover { background: #333; transform: translateY(-1px); }

    /* ─── HERO / PAGE TITLE ─── */
    .page-hero { padding: 52px 0 36px; border-bottom: 1px solid var(--border); }
    .page-hero h1 { font-size: clamp(28px, 4vw, 40px); font-weight: 800; letter-spacing: -1px; color: var(--text-primary); margin-bottom: 10px; }
    .page-hero p { font-size: 16px; color: var(--text-secondary); max-width: 560px; }

    /* ─── FILTERS ─── */
    .filters-section { padding: 28px 0; border-bottom: 1px solid var(--border); }
    .filters-bar { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
    .filters-pills { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; flex: 1; }
    .pill {
      background: none; border: 1.5px solid var(--border);
      padding: 6px 14px; font-size: 13px; font-weight: 500;
      color: var(--text-secondary); border-radius: var(--radius-full);
      transition: all var(--transition); white-space: nowrap;
    }
    .pill:hover { border-color: var(--border-hover); color: var(--text-primary); background: var(--tag-bg); }
    .pill.active { background: var(--text-primary); border-color: var(--text-primary); color: white; }

    .search-wrapper { position: relative; flex-shrink: 0; }
    .search-wrapper i { position: absolute; left: 10px; top: 50%; transform: translateY(-50%); color: var(--text-muted); font-size: 15px; pointer-events: none; }
    .search-input {
      background: var(--surface); border: 1.5px solid var(--border);
      padding: 7px 14px 7px 34px; font-size: 13.5px; font-family: inherit;
      color: var(--text-primary); border-radius: var(--radius-full);
      width: 220px; transition: border-color var(--transition), box-shadow var(--transition);
      outline: none;
    }
    .search-input::placeholder { color: var(--text-muted); }
    .search-input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(0,114,245,0.12); }

    /* ─── FEATURED ─── */
    .featured-section { padding: 52px 0 40px; }
    .section-label { font-size: 11px; font-weight: 700; color: var(--accent); letter-spacing: 0.1em; text-transform: uppercase; margin-bottom: 24px; display: flex; align-items: center; gap: 8px; }
    .section-label::after { content: ''; flex: 1; height: 1px; background: var(--border); }

    .featured-grid { display: grid; grid-template-columns: 2fr 1fr; grid-template-rows: auto auto; gap: 20px; }
    .featured-card {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: var(--radius-lg); overflow: hidden;
      transition: box-shadow var(--transition), transform var(--transition), border-color var(--transition);
      position: relative; display: flex; flex-direction: column;
    }
    .featured-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-2px); border-color: var(--border-hover); }
    .featured-card.main { grid-row: 1 / 3; }

    .card-visual {
      width: 100%; aspect-ratio: 16/9; object-fit: cover;
      background: linear-gradient(135deg, #0f172a 0%, #1e3a5f 50%, #0072F5 100%);
      flex-shrink: 0; position: relative; overflow: hidden;
      display: flex; align-items: center; justify-content: center;
    }
    .featured-card.main .card-visual { aspect-ratio: 16/9; min-height: 280px; }
    .side-card .card-visual { aspect-ratio: 16/7; min-height: 140px; }

    .card-visual-pattern {
      position: absolute; inset: 0;
      background-image: radial-gradient(circle at 25% 25%, rgba(255,255,255,0.07) 0%, transparent 50%),
                        radial-gradient(circle at 75% 75%, rgba(0,114,245,0.3) 0%, transparent 50%);
    }
    .card-visual-content { position: relative; z-index: 1; text-align: center; padding: 24px; }
    .stat-display { display: flex; flex-direction: column; align-items: center; gap: 8px; }
    .stat-number { font-size: clamp(36px, 5vw, 56px); font-weight: 800; color: white; letter-spacing: -2px; line-height: 1; }
    .stat-label { font-size: 13px; color: rgba(255,255,255,0.7); font-weight: 500; }

    .mini-stats { display: flex; gap: 16px; justify-content: center; margin-top: 16px; flex-wrap: wrap; }
    .mini-stat { text-align: center; }
    .mini-stat-num { font-size: 20px; font-weight: 800; color: white; letter-spacing: -0.5px; }
    .mini-stat-lbl { font-size: 11px; color: rgba(255,255,255,0.6); }

    .card-body { padding: 22px 24px 24px; flex: 1; display: flex; flex-direction: column; }
    .card-meta { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
    .card-tag {
      font-size: 11px; font-weight: 600; padding: 3px 9px;
      border-radius: var(--radius-full); letter-spacing: 0.03em;
    }
    .tag-engineering { background: #EFF6FF; color: #1D4ED8; }
    .tag-general { background: #F0FDF4; color: #166534; }
    .tag-customers { background: #FFF7ED; color: #C2410C; }
    .tag-security { background: #FDF4FF; color: #7C3AED; }
    .tag-community { background: #F0F9FF; color: #0369A1; }
    .tag-company { background: #FAFAFA; color: #374151; }
    .tag-default { background: var(--tag-bg); color: var(--tag-text); }

    .card-date { font-size: 12.5px; color: var(--text-muted); }
    .card-title { font-size: clamp(16px, 2vw, 20px); font-weight: 700; color: var(--text-primary); letter-spacing: -0.4px; line-height: 1.3; margin-bottom: 10px; }
    .featured-card.main .card-title { font-size: clamp(18px, 2.5vw, 24px); }
    .card-excerpt { font-size: 14px; color: var(--text-secondary); line-height: 1.65; flex: 1; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; margin-bottom: 18px; }
    .card-author { display: flex; align-items: center; gap: 9px; margin-top: auto; }
    .avatar { width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 700; color: white; flex-shrink: 0; }
    .author-name { font-size: 13px; font-weight: 500; color: var(--text-secondary); }
    .read-more { display: inline-flex; align-items: center; gap: 5px; font-size: 13px; font-weight: 600; color: var(--accent); margin-left: auto; transition: gap var(--transition); }
    .read-more:hover { gap: 8px; }

    /* ─── LATEST NEWS ─── */
    .latest-section { padding: 20px 0 52px; }
    .latest-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 28px; }
    .latest-header h2 { font-size: 22px; font-weight: 700; letter-spacing: -0.5px; }

    .posts-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }

    .post-card {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: var(--radius-lg); overflow: hidden;
      display: flex; flex-direction: column;
      transition: box-shadow var(--transition), transform var(--transition), border-color var(--transition);
    }
    .post-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-2px); border-color: var(--border-hover); }
    .post-card-visual {
      width: 100%; aspect-ratio: 16/8;
      display: flex; align-items: center; justify-content: center;
      position: relative; overflow: hidden;
    }
    .post-card-body { padding: 18px 20px 20px; flex: 1; display: flex; flex-direction: column; }
    .post-card-meta { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; flex-wrap: wrap; }
    .post-card-title { font-size: 15px; font-weight: 700; color: var(--text-primary); letter-spacing: -0.3px; line-height: 1.35; margin-bottom: 8px; }
    .post-card-excerpt { font-size: 13.5px; color: var(--text-secondary); line-height: 1.6; flex: 1; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; margin-bottom: 14px; }
    .post-card-footer { display: flex; align-items: center; gap: 8px; margin-top: auto; }
    .post-author-name { font-size: 12.5px; color: var(--text-muted); font-weight: 500; }

    /* No results */
    .no-results { grid-column: 1/-1; text-align: center; padding: 72px 24px; color: var(--text-muted); }
    .no-results i { font-size: 40px; margin-bottom: 14px; display: block; }
    .no-results h3 { font-size: 17px; font-weight: 600; color: var(--text-secondary); margin-bottom: 8px; }
    .no-results p { font-size: 14px; }

    /* Show more */
    .show-more-wrapper { text-align: center; margin-top: 40px; }
    .btn-outline {
      background: none; border: 1.5px solid var(--border);
      padding: 11px 28px; font-size: 14px; font-weight: 600; color: var(--text-primary);
      border-radius: var(--radius-full); display: inline-flex; align-items: center; gap: 8px;
      transition: all var(--transition);
    }
    .btn-outline:hover { border-color: var(--text-primary); background: var(--text-primary); color: white; }
    .btn-outline:hover i { color: white; }
    .btn-outline i { color: var(--text-muted); font-size: 15px; }
    .btn-outline.hidden { display: none; }

    /* ─── CTA BANNER ─── */
    .cta-section { padding: 0 0 64px; }
    .cta-block {
      background: var(--text-primary); border-radius: var(--radius-lg); overflow: hidden;
      padding: 56px 64px; display: grid; grid-template-columns: 1fr auto; gap: 40px; align-items: center;
    }
    .cta-block h2 { font-size: clamp(22px, 3vw, 30px); font-weight: 800; color: white; letter-spacing: -0.6px; line-height: 1.25; margin-bottom: 10px; }
    .cta-block h2 em { font-style: normal; color: var(--accent); }
    .cta-block p { font-size: 15px; color: rgba(255,255,255,0.65); }
    .cta-actions { display: flex; gap: 10px; flex-wrap: wrap; flex-shrink: 0; }
    .btn-white {
      background: white; color: var(--text-primary); border: none;
      padding: 11px 22px; font-size: 14px; font-weight: 700;
      border-radius: var(--radius-full); transition: transform 0.15s, box-shadow 0.15s;
    }
    .btn-white:hover { transform: translateY(-1px); box-shadow: 0 4px 16px rgba(0,0,0,0.2); }
    .btn-outline-white {
      background: none; border: 1.5px solid rgba(255,255,255,0.3); color: white;
      padding: 11px 22px; font-size: 14px; font-weight: 600; border-radius: var(--radius-full);
      transition: border-color var(--transition), background var(--transition);
    }
    .btn-outline-white:hover { border-color: white; background: rgba(255,255,255,0.1); }

    .enterprise-strip {
      background: #F4F4F5; border-radius: var(--radius-lg); padding: 22px 32px;
      display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-top: 16px;
    }
    .enterprise-strip p { font-size: 14px; color: var(--text-secondary); }
    .enterprise-strip strong { color: var(--text-primary); }
    .btn-accent {
      background: var(--accent); color: white; border: none;
      padding: 9px 20px; font-size: 13.5px; font-weight: 600; border-radius: var(--radius-full);
      transition: background var(--transition), transform 0.1s; flex-shrink: 0;
    }
    .btn-accent:hover { background: var(--accent-hover); transform: translateY(-1px); }

    /* ─── FOOTER ─── */
    .footer {
      background: var(--text-primary); color: rgba(255,255,255,0.6);
      padding: 60px 0 32px;
    }
    .footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px 24px; margin-bottom: 48px; }
    .footer-col-title { font-size: 12px; font-weight: 700; color: white; letter-spacing: 0.06em; text-transform: uppercase; margin-bottom: 14px; }
    .footer-links { display: flex; flex-direction: column; gap: 9px; }
    .footer-link { font-size: 13px; color: rgba(255,255,255,0.55); transition: color var(--transition); }
    .footer-link:hover { color: white; }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1); padding-top: 28px;
      display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 16px;
    }
    .footer-logo { display: flex; align-items: center; gap: 9px; font-size: 14px; font-weight: 700; color: white; }
    .footer-logo-icon { width: 24px; height: 24px; background: white; border-radius: 5px; display: flex; align-items: center; justify-content: center; }
    .footer-logo-icon i { color: var(--text-primary); font-size: 13px; }
    .footer-status { display: flex; align-items: center; gap: 8px; font-size: 13px; }
    .status-dot { width: 7px; height: 7px; border-radius: 50%; background: #22C55E; animation: pulse 2s infinite; }
    @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }
    .footer-copy { font-size: 12.5px; }

    /* ─── HIDDEN STATE ─── */
    .post-hidden { display: none !important; }

    /* ─── RESPONSIVE ─── */
    @media (max-width: 1024px) {
      .featured-grid { grid-template-columns: 1fr 1fr; }
      .featured-card.main { grid-column: 1 / -1; grid-row: auto; }
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
    }
    @media (max-width: 768px) {
      .container { padding: 0 16px; }
      .main-nav { display: none; }
      .featured-grid { grid-template-columns: 1fr; }
      .posts-grid { grid-template-columns: repeat(2, 1fr); }
      .cta-block { grid-template-columns: 1fr; padding: 36px 28px; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
      .search-input { width: 180px; }
    }
    @media (max-width: 540px) {
      .posts-grid { grid-template-columns: 1fr; }
      .filters-bar { flex-direction: column; align-items: flex-start; }
      .search-wrapper { width: 100%; }
      .search-input { width: 100%; }
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .enterprise-strip { flex-direction: column; align-items: flex-start; }
    }
  </style>
</head>
