<script>
(function () {
  'use strict';

  // ── State ──
  let activeCategory = 'all';
  let searchQuery = '';
  let extraRevealed = false;

  // ── Elements ──
  const pills       = document.querySelectorAll('.pill[data-category]');
  const searchInput = document.getElementById('searchInput');
  const postsGrid   = document.getElementById('postsGrid');
  const showMoreBtn = document.getElementById('showMoreBtn');
  const noResults   = document.getElementById('noResults');
  const featuredSec = document.getElementById('featuredSection');
  const featuredCards = featuredSec.querySelectorAll('article.featured-card');

  // ── Category map: pill value → card data-category ──
  const CATEGORY_MAP = {
    'all': null,
    'engineering': 'engineering',
    'community': 'community',
    'company-news': 'company-news',
    'customers': 'customers',
    'v0': 'v0',
    'security': 'security',
    'changelog': 'changelog',
    'press': 'press',
  };

  function getPostCards() {
    return Array.from(postsGrid.querySelectorAll('article.post-card'));
  }

  function matchesFilter(card) {
    const cat   = card.getAttribute('data-category') || '';
    const title = (card.getAttribute('data-title') || '').toLowerCase();
    const search= (card.getAttribute('data-search') || '').toLowerCase();
    const isExtra = card.getAttribute('data-extra') === 'true';

    // If extra and not yet revealed, never show
    if (isExtra && !extraRevealed) return false;

    const catMatch = activeCategory === 'all' || cat === activeCategory;
    const q = searchQuery.trim().toLowerCase();
    const searchMatch = q === '' || title.includes(q) || search.includes(q);

    return catMatch && searchMatch;
  }

  function applyFilters() {
    const cards = getPostCards();
    let visible = 0;

    cards.forEach(card => {
      const show = matchesFilter(card);
      card.style.display = show ? '' : 'none';
      if (show) visible++;
    });

    noResults.style.display = visible === 0 ? 'flex' : 'none';
    if (visible === 0) noResults.style.display = 'block';

    // Featured section visibility
    const featQ = searchQuery.trim().toLowerCase();
    featuredCards.forEach(card => {
      const cat = card.getAttribute('data-category') || '';
      const title = (card.getAttribute('data-title') || '').toLowerCase();
      const srch = (card.getAttribute('data-search') || '').toLowerCase();
      const catOk = activeCategory === 'all' || cat === activeCategory;
      const searchOk = featQ === '' || title.includes(featQ) || srch.includes(featQ);
      card.style.display = (catOk && searchOk) ? '' : 'none';
    });

    // Show/hide the "Show more" button
    const hasHiddenExtra = Array.from(postsGrid.querySelectorAll('article.post-card[data-extra="true"]'))
      .some(c => !extraRevealed || !matchesFilter(c));

    showMoreBtn.parentElement.style.display =
      (!extraRevealed && activeCategory === 'all' && searchQuery === '') ? 'block' : 'none';
  }

  // ── Pill click ──
  pills.forEach(pill => {
    pill.addEventListener('click', () => {
      pills.forEach(p => p.classList.remove('active'));
      pill.classList.add('active');
      activeCategory = pill.getAttribute('data-category');
      applyFilters();
    });
  });

  // ── Search ──
  searchInput.addEventListener('input', () => {
    searchQuery = searchInput.value;
    applyFilters();
  });

  // ── Show more ──
  showMoreBtn.addEventListener('click', () => {
    extraRevealed = true;
    // Reveal all extra posts
    postsGrid.querySelectorAll('article.post-card[data-extra="true"]').forEach(card => {
      card.classList.remove('post-hidden');
      card.style.display = '';
      // Animate in
      card.style.opacity = '0';
      card.style.transform = 'translateY(12px)';
      requestAnimationFrame(() => {
        card.style.transition = 'opacity 0.35s ease, transform 0.35s ease';
        card.style.opacity = '1';
        card.style.transform = 'translateY(0)';
      });
    });
    showMoreBtn.parentElement.style.display = 'none';
    applyFilters();
  });

  // ── Initial render ──
  applyFilters();

})();
</script>

